    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum Action {
        Launch {
            grain: Vec<u8>,
            program: Vec<u8>,
            read: Vec<Vec<u8>>,
            write: Vec<Vec<u8>>,
            exec: Vec<Vec<u8>>,
            broker: Vec<Vec<u8>>,
            member: Vec<Vec<u8>>,
            hidden: Vec<Vec<u8>>,
        },
        Kill {
            grain: Vec<u8>,
        },
        Refuse {
            grain: Vec<u8>,
            grain_refusal: GrainRefusal,
        },
    }

    impl Action {
        pub fn decode(b: &[u8]) -> Result<Self, Refusal> {
            let mut c = Cursor { b, i: 0 };
            let at = c.i;
            let action = match c.byte()? {
                1 => {
                    let grain = c.bytes(4096)?;
                    let program = c.path(4096)?;
                    let read = c.paths(4096)?;
                    let write = c.paths(4096)?;
                    let exec = c.paths(4096)?;
                    let broker = c.paths(4096)?;
                    let member = c.paths(4096)?;
                    let hidden = c.paths(4096)?;
                    Action::Launch {
                        grain,
                        program,
                        read,
                        write,
                        exec,
                        broker,
                        member,
                        hidden,
                    }
                }
                2 => {
                    let grain = c.bytes(4096)?;
                    Action::Kill { grain }
                }
                3 => {
                    let grain = c.bytes(4096)?;
                    let grain_refusal = c.one_of(GrainRefusal::from_code)?;
                    Action::Refuse {
                        grain,
                        grain_refusal,
                    }
                }
                tag => return Err(Refusal::BadTag { offset: at, tag }),
            };
            c.end()?;
            Ok(action)
        }

        pub fn encode(&self) -> Result<Vec<u8>, Refusal> {
            let mut out = Vec::new();
            match self {
                Action::Launch {
                    grain,
                    program,
                    read,
                    write,
                    exec,
                    broker,
                    member,
                    hidden,
                } => {
                    out.push(1);
                    put_bytes(&mut out, grain, 4096)?;
                    put_path(&mut out, program, 4096)?;
                    put_paths(&mut out, read, 4096)?;
                    put_paths(&mut out, write, 4096)?;
                    put_paths(&mut out, exec, 4096)?;
                    put_paths(&mut out, broker, 4096)?;
                    put_paths(&mut out, member, 4096)?;
                    put_paths(&mut out, hidden, 4096)?;
                }
                Action::Kill { grain } => {
                    out.push(2);
                    put_bytes(&mut out, grain, 4096)?;
                }
                Action::Refuse {
                    grain,
                    grain_refusal,
                } => {
                    out.push(3);
                    put_bytes(&mut out, grain, 4096)?;
                    out.push(grain_refusal.code());
                }
            }
            Ok(out)
        }
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum Report {
        Started {
            grain: Vec<u8>,
            at_ms: u64,
        },
        Exited {
            grain: Vec<u8>,
            status: u32,
            at_ms: u64,
        },
        Failed {
            grain: Vec<u8>,
            launch_failure: LaunchFailure,
            at_ms: u64,
        },
        Tick {
            at_ms: u64,
        },
    }

    impl Report {
        pub fn decode(b: &[u8]) -> Result<Self, Refusal> {
            let mut c = Cursor { b, i: 0 };
            let at = c.i;
            let report = match c.byte()? {
                1 => {
                    let grain = c.bytes(4096)?;
                    let at_ms = c.u64()?;
                    Report::Started { grain, at_ms }
                }
                2 => {
                    let grain = c.bytes(4096)?;
                    let status = c.u32()? as u32;
                    let at_ms = c.u64()?;
                    Report::Exited {
                        grain,
                        status,
                        at_ms,
                    }
                }
                3 => {
                    let grain = c.bytes(4096)?;
                    let launch_failure = c.one_of(LaunchFailure::from_code)?;
                    let at_ms = c.u64()?;
                    Report::Failed {
                        grain,
                        launch_failure,
                        at_ms,
                    }
                }
                4 => {
                    let at_ms = c.u64()?;
                    Report::Tick { at_ms }
                }
                tag => return Err(Refusal::BadTag { offset: at, tag }),
            };
            c.end()?;
            Ok(report)
        }

        pub fn encode(&self) -> Result<Vec<u8>, Refusal> {
            let mut out = Vec::new();
            match self {
                Report::Started { grain, at_ms } => {
                    out.push(1);
                    put_bytes(&mut out, grain, 4096)?;
                    out.extend_from_slice(&at_ms.to_le_bytes());
                }
                Report::Exited {
                    grain,
                    status,
                    at_ms,
                } => {
                    out.push(2);
                    put_bytes(&mut out, grain, 4096)?;
                    out.extend_from_slice(&status.to_le_bytes());
                    out.extend_from_slice(&at_ms.to_le_bytes());
                }
                Report::Failed {
                    grain,
                    launch_failure,
                    at_ms,
                } => {
                    out.push(3);
                    put_bytes(&mut out, grain, 4096)?;
                    out.push(launch_failure.code());
                    out.extend_from_slice(&at_ms.to_le_bytes());
                }
                Report::Tick { at_ms } => {
                    out.push(4);
                    out.extend_from_slice(&at_ms.to_le_bytes());
                }
            }
            Ok(out)
        }
    }
